			return ((GDynamicColumnTableModel<object,object>) model).getDataSource();
		}
		return null;
	}

	private class AndList {
		private List<ColumnConstraintSet<R,object>> list = new();

		void addConstraintSet(ColumnConstraintSet<R,object> constraintSet) {
			list.add(constraintSet);
		}

		bool acceptsRow(R rowObject) {
			foreach (ColumnConstraintSet<R,object> constraintSet in list) {
				if (!constraintSet.accepts(rowObject, tableFilterContext)) {
					return false;
				}
			}
			return true;
		}
	}

	private class OrList {
		private List<AndList> list = new();

		void addAndList(AndList andList) {
			list.add(andList);
		}

		bool acceptsRow(R rowObject) {
			foreach (AndList andList in list) {
				if (andList.acceptsRow(rowObject)) {
					return true;
				}
			}
			return false;
		}
	}

